package com.bank.flink.cdcsync;

// One CDC change with a log offset (binlog position / WAL LSN analogue).
class ChangeRecord {
    enum Op { INSERT, UPDATE, DELETE }

    private final Op op;
    private final AccountImage before;
    private final AccountImage after;
    private final long logOffset;

    ChangeRecord(Op op, AccountImage before, AccountImage after, long logOffset) {
        this.op = op;
        this.before = before;
        this.after = after;
        this.logOffset = logOffset;
    }

    Op getOp() { return op; }
    AccountImage getBefore() { return before; }
    AccountImage getAfter() { return after; }
    long getLogOffset() { return logOffset; }
}
