package com.bank.flink.cdcsync;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Models a CDC source: snapshot existing rows, then stream live changes.
class CdcSource {
    private static final Logger log = Logger.getLogger(CdcSource.class.getName());

    // Phase 1: snapshot of existing accounts -> emitted as INSERTs.
    List<ChangeRecord> snapshot() {
        log.info("CDC snapshot phase: reading current accounts table");
        List<ChangeRecord> out = new ArrayList<>();
        out.add(new ChangeRecord(ChangeRecord.Op.INSERT, null,
                new AccountImage("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")), 100));
        out.add(new ChangeRecord(ChangeRecord.Op.INSERT, null,
                new AccountImage("CUR3001", "Priya Sharma", new BigDecimal("250000")), 101));
        return out;
    }

    // Phase 2: live binlog/WAL changes after the snapshot boundary.
    List<ChangeRecord> binlogChanges() {
        log.info("CDC streaming phase: tailing binlog from offset 102");
        List<ChangeRecord> out = new ArrayList<>();
        // Rajesh transfers 50000 out: 1,000,000 -> 950,000.
        out.add(new ChangeRecord(ChangeRecord.Op.UPDATE,
                new AccountImage("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")),
                new AccountImage("SAV2001", "Rajesh Kumar", new BigDecimal("950000")), 102));
        // New account opened.
        out.add(new ChangeRecord(ChangeRecord.Op.INSERT, null,
                new AccountImage("SAV2002", "Anil Mehta", new BigDecimal("75000")), 103));
        // Priya closes her account.
        out.add(new ChangeRecord(ChangeRecord.Op.DELETE,
                new AccountImage("CUR3001", "Priya Sharma", new BigDecimal("250000")), null, 104));
        return out;
    }
}
