package com.bank.flink.cdcsync;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Consumes the changelog into a materialized sink and checkpoints the offset
// so a restart resumes from exactly where it left off (exactly-once).
class CheckpointedPipeline {
    private static final Logger log = Logger.getLogger(CheckpointedPipeline.class.getName());

    private final Map<String, AccountImage> sink = new LinkedHashMap<>();
    private long checkpointedOffset = -1;
    private long currentOffset = -1;

    void apply(ChangeRecord r) {
        switch (r.getOp()) {
            case INSERT:
                sink.put(r.getAfter().getAccountId(), r.getAfter());
                break;
            case UPDATE:
                // retract old, add new (upsert by PK)
                sink.put(r.getAfter().getAccountId(), r.getAfter());
                break;
            case DELETE:
                sink.remove(r.getBefore().getAccountId());
                break;
        }
        currentOffset = r.getLogOffset();
        log.info(() -> r.getOp() + " applied, offset=" + currentOffset);
    }

    // Flink checkpoint: persist the consumed log offset with sink state.
    void checkpoint() {
        checkpointedOffset = currentOffset;
        log.info(() -> "CHECKPOINT at offset " + checkpointedOffset);
    }

    // Simulate crash + restore: resume from the checkpointed offset.
    long restoreAndResumeOffset() {
        log.warning(() -> "RESTART -> resume from checkpointed offset " + checkpointedOffset);
        currentOffset = checkpointedOffset;
        return checkpointedOffset + 1; // next offset to read
    }

    Map<String, AccountImage> sink() { return sink; }
}
