package com.bank.flink.cdcsync;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FlinkCdcDemo {
    private static final Logger log = Logger.getLogger(FlinkCdcDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        CdcSource source = new CdcSource();
        CheckpointedPipeline pipeline = new CheckpointedPipeline();

        // Phase 1: snapshot -> inserts.
        for (ChangeRecord r : source.snapshot()) pipeline.apply(r);
        log.info("after snapshot sink=" + pipeline.sink());

        // Phase 2: stream live changes.
        List<ChangeRecord> changes = source.binlogChanges();
        pipeline.apply(changes.get(0)); // Rajesh update
        pipeline.apply(changes.get(1)); // new account
        pipeline.checkpoint();          // checkpoint at offset 103

        pipeline.apply(changes.get(2)); // Priya delete (offset 104, NOT checkpointed yet)

        // Crash before next checkpoint: resume from checkpointed offset 103.
        long resumeFrom = pipeline.restoreAndResumeOffset();
        log.info("resume reading from offset " + resumeFrom);
        log.info("final mirrored table=" + pipeline.sink());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
